# -*- coding: utf-8 -*-
"""`plan.get` — công cụ do TÁC TỬ tự viết.

Xem chi tiết toàn văn kế hoạch đang chạy: mục tiêu, danh sách các bước, công cụ, cổng an toàn, trạng thái hoàn thành và hiện vật nghiệm thu.
"""

from __future__ import annotations

import json
from pathlib import Path
import sqlite3
from typing import Any, Dict, Optional


def lay_ke_hoach_hien_tai(db_path: Optional[str] = None) -> Optional[Dict[str, Any]]:
    candidates = []
    if db_path:
        candidates.append(Path(db_path))
    candidates.extend([
        Path(".eide/store.sqlite"),
        Path.cwd() / ".eide" / "store.sqlite",
        Path(__file__).resolve().parent.parent / "store.sqlite",
        Path(__file__).resolve().parent.parent.parent / ".eide" / "store.sqlite"
    ])
    for p in candidates:
        if p.is_file():
            try:
                conn = sqlite3.connect(p)
                cursor = conn.cursor()
                cursor.execute("SELECT canonical_json FROM artefacts WHERE id = 'plan:current'")
                row = cursor.fetchone()
                conn.close()
                if row and row[0]:
                    data = json.loads(row[0])
                    if isinstance(data, dict):
                        return data
            except Exception:
                continue
    return None


def thuc_thi_plan_get(db_path: Optional[str] = None) -> Dict[str, Any]:
    plan = lay_ke_hoach_hien_tai(db_path)
    if not plan or not plan.get("steps"):
        return {
            "co_ke_hoach": False,
            "thong_bao": "Hiện không có kế hoạch nào đang chạy hoặc chưa có kế hoạch được duyệt."
        }

    steps = plan.get("steps", [])
    da_xong = sum(1 for s in steps if s.get("xong") is True)
    return {
        "co_ke_hoach": True,
        "muc_tieu": plan.get("muc_tieu", ""),
        "trang_thai": plan.get("trang_thai", ""),
        "run_id": plan.get("run_id", ""),
        "tong_buoc": len(steps),
        "da_xong": da_xong,
        "buoc": [
            {
                "so": idx + 1,
                "viec": s.get("viec", ""),
                "cong_cu": s.get("cong_cu", ""),
                "cong": s.get("cong", ""),
                "hien_vat": s.get("hien_vat", ""),
                "xong": s.get("xong", False),
                "ghi_chu": s.get("ghi_chu", ""),
                "chi_phi": s.get("chi_phi", "")
            }
            for idx, s in enumerate(steps)
        ],
        "gia_dinh": plan.get("gia_dinh", []),
        "ngoai_pham_vi": plan.get("ngoai_pham_vi", [])
    }


def dang_ky(r) -> None:
    @r.tool("plan.get", "Điều phối",
            "Xem toàn văn chi tiết kế hoạch đang chạy: mục tiêu, các bước, công cụ, cổng, hiện vật và trạng thái",
            {"type": "object", "properties": {}, "required": []},
            risk="R1", core=False, keywords=["plan", "kế hoạch", "tiến độ"])
    def plan_get(ctx: Any = None) -> Dict[str, Any]:
        return thuc_thi_plan_get()

